import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"热键","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/hotkeys.md","filePath":"zh-CN/user-guide/hotkeys.md","lastUpdated":1784513933000}'),a={name:"zh-CN/user-guide/hotkeys.md"};function c(l,t,s,h,i,n){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="热键" tabindex="-1">热键 <a class="header-anchor" href="#热键" aria-label="Permalink to &quot;热键&quot;">​</a></h1><p>下面所有全局与应用内热键都可以在<strong>设置 → 热键</strong>里重新绑定；这里列出的是默认值。设置界面本身见 <a href="./settings/hotkeys-page.html">设置 → 热键页面</a>。</p><h2 id="全局热键" tabindex="-1">全局热键 <a class="header-anchor" href="#全局热键" aria-label="Permalink to &quot;全局热键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>呼出/隐藏快速窗口</td><td>双击 <code>Ctrl</code></td><td>也可以设置成完整组合键(例如 <code>Alt+Space</code>)而不是双击模式。</td></tr><tr><td>快速切换</td><td><code>Ctrl+G</code></td><td>在内嵌(嵌入资源管理器)搜索栏和主窗口之间切换。</td></tr><tr><td>选中下一项</td><td><code>Ctrl+N</code></td><td>与方向键的下键效果相同。</td></tr><tr><td>选中上一项</td><td><code>Ctrl+P</code></td><td>与方向键的上键效果相同。</td></tr><tr><td>跳转到结果 1–9</td><td><code>Ctrl</code> + 数字</td><td>修饰键可自定义;数字固定为 1–9。快速窗口里每个可见结果旁边都会显示对应快捷键的小徽章，不用自己数行数。</td></tr><tr><td>打开动作菜单</td><td><code>Ctrl+O</code></td><td>与在选中结果上按方向键右键效果相同。</td></tr><tr><td>从选中项补全</td><td><code>Ctrl+Tab</code></td><td>在快速窗口里，用选中结果的名称/路径填充搜索框。</td></tr><tr><td>QuickLook 预览</td><td><code>Alt+P</code></td><td>切换选中结果的预览面板。</td></tr><tr><td>上一条关键字历史</td><td><code>Alt+Up</code></td><td>向前翻阅最近输入过的搜索词。</td></tr><tr><td>下一条关键字历史</td><td><code>Alt+Down</code></td><td>向后翻阅最近输入过的搜索词。</td></tr><tr><td>删除当前关键字历史</td><td><code>Shift+Delete</code></td><td></td></tr><tr><td>打开完整窗口</td><td><em>(无)</em></td><td>直接打开完整窗口并带上当前搜索内容——效果和点击快速窗口自带的菜单按钮(☰)选&quot;显示主窗口&quot;一样,只是省了点菜单这一步。默认未绑定;可在<strong>设置 → 热键</strong>里自行设置。</td></tr><tr><td>初始面板下一个标签</td><td><code>Ctrl+Right</code></td><td>到最后一个标签后会循环回第一个。只有<a href="./settings/startup-panel.html">初始面板</a>正在显示时才生效——否则这个按键正常做它原本的事(比如在输入查询词时移动光标)。</td></tr><tr><td>初始面板上一个标签</td><td><code>Ctrl+Left</code></td><td>到第一个标签后会循环回最后一个。同样只有面板显示时才生效。</td></tr></tbody></table><h2 id="快速导航-鼠标" tabindex="-1">快速导航(鼠标) <a class="header-anchor" href="#快速导航-鼠标" aria-label="Permalink to &quot;快速导航(鼠标)&quot;">​</a></h2><p>默认启用，每种触发方式都可单独在设置里开关：</p><ul><li>在桌面或资源管理器窗口的空白处<strong>双击左键</strong>触发快速导航。</li><li>在桌面或资源管理器窗口的空白处、受支持的第三方文件管理器(Directory Opus、Total Commander、 XYplorer 等)的文件列表区域、或原生的打开/保存/浏览文件夹对话框里<strong>点击中键</strong>触发快速导航。这些 其它窗口只响应中键——双击在那里已经是&quot;打开这一项&quot;的意思，所以没有把双击挪作他用。</li></ul><p>无论哪种方式触发，都会弹出一个级联菜单，内容是你的收藏夹、历史记录和配置好的快捷文件夹(见 <a href="./settings/favorites.html">设置 → 收藏夹</a>和<a href="./settings/history.html">设置 → 历史记录</a>)——插件也可以往里加 自己的条目，比如你在 <code>wincmd.ini</code> 里配置过 Total Commander 的 Directory Hotlist 的话，它也会出现在 这里。点击文件夹会让目标窗口跳转过去；点击文件也会跳转过去，并在其所在文件夹中选中该文件，而不是 打开它——唯一的例外是桌面，那里没有可供跳转的现有窗口面板，所以在桌面上点击文件夹或文件会直接打 开它，效果和双击一样。如果是在文件选择器里，点击文件则是让对话框跳转到该文件所在的文件夹——绝不 会替你自动确认&quot;打开&quot;/&quot;保存&quot;。</p><h2 id="硬编码按键-不可配置" tabindex="-1">硬编码按键(不可配置) <a class="header-anchor" href="#硬编码按键-不可配置" aria-label="Permalink to &quot;硬编码按键(不可配置)&quot;">​</a></h2><p>无论热键设置如何，以下按键始终保持相同行为：</p><table tabindex="0"><thead><tr><th>按键</th><th>场景</th><th>行为</th></tr></thead><tbody><tr><td><code>Escape</code></td><td>任意场景</td><td>若搜索框有内容则清空;否则关闭窗口(或退出动作菜单)。</td></tr><tr><td><code>Enter</code></td><td>结果列表</td><td>打开选中结果。</td></tr><tr><td><code>Ctrl+Enter</code></td><td>结果列表</td><td>在资源管理器中定位该结果，而不是打开它。</td></tr><tr><td><code>Ctrl+Shift+Enter</code></td><td>结果列表</td><td>以管理员身份打开该结果。</td></tr><tr><td>左/右方向键</td><td>动作菜单</td><td>返回上一级菜单 / 进入子菜单。</td></tr><tr><td><code>Backspace</code></td><td>动作菜单</td><td>当搜索框已为空时，退出动作菜单。</td></tr><tr><td><code>Alt+Space</code> / <code>Alt+F4</code></td><td>快速窗口、主窗口、设置窗口</td><td>这几个窗口上都会被屏蔽——不会弹出 Windows 的系统菜单，<code>Alt+F4</code> 也不会关闭窗口。</td></tr></tbody></table><h2 id="插件动作热键" tabindex="-1">插件动作热键 <a class="header-anchor" href="#插件动作热键" aria-label="Permalink to &quot;插件动作热键&quot;">​</a></h2><p>插件可以注册自己的动作并附带一个默认热键(例如复制路径、以管理员身份运行)。这些会显示在 <strong>设置 → 热键 → 插件动作</strong> 里，按注册它们的插件分组，重新绑定方式和内置热键相同。</p><h2 id="进程黑名单" tabindex="-1">进程黑名单 <a class="header-anchor" href="#进程黑名单" aria-label="Permalink to &quot;进程黑名单&quot;">​</a></h2><p>如果 SwiftList 的全局热键和某个应用(比如会独占键盘原始输入的游戏)冲突，把该进程加入<strong>进程黑名 单</strong>即可——详见<a href="./settings/hotkeys-page.html#process-blacklist">设置 → 热键页面</a>。当黑名单里的进程处 于前台时，SwiftList 的全局热键、按键拦截，以及上面的快速导航鼠标触发都会被完全放行，不会拦截。</p><p>任何真正全屏的前台应用都会自动获得同样的效果，不需要手动加入黑名单。无论哪种情况，当前活动窗口 如果是文件选择器，都会被豁免，快速导航依然可以正常使用。</p>',16)])])}const m=d(a,[["render",c]]);export{u as __pageData,m as default};
